import { useState, type KeyboardEvent } from 'react';
import { JxChip, JxInputField } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
  helperText?: string;
}

function ArticleTagPicker({
  value,
  defaultValue,
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  helperText = 'Enter или запятая добавляет тег, Backspace удаляет последний',
}: ArticleTagPickerProps) {
  const [uncontrolled, setUncontrolled] = useState<string[]>(defaultValue ?? []);
  const [draft, setDraft] = useState('');

  const tags = value ?? uncontrolled;

  const commit = (next: string[]) => {
    if (value === undefined) {
      setUncontrolled(next);
    }
    onChange?.(next);
  };

  const addTag = (raw: string) => {
    const tag = raw.trim();
    setDraft('');
    if (tag === '' || tags.includes(tag)) {
      return;
    }
    commit([...tags, tag]);
  };

  const removeTag = (tag: string) => {
    commit(tags.filter((item) => item !== tag));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(draft);
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      commit(tags.slice(0, -1));
    }
  };

  return (
    <div style={{ display: 'grid', gap: '8px' }}>
      <JxInputField
        label={label}
        placeholder={placeholder}
        helperText={helperText}
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => addTag(draft)}
      />
      {tags.length > 0 && (
        <div
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

export default ArticleTagPicker;

